-- Kitabwalah Vendor Platform · PostgreSQL 15+
CREATE TYPE vendor_status AS ENUM ('PENDING_REVIEW','UNDER_REVIEW','APPROVED','REJECTED','ACTION_REQUIRED');
CREATE TYPE product_status AS ENUM ('ACTIVE','INACTIVE','DRAFT','ARCHIVED');
CREATE TYPE order_status AS ENUM ('NEW','PROCESSING','READY_FOR_DISPATCH','DISPATCHED','DELIVERED','RETURNED','CANCELLED');
CREATE TYPE return_status AS ENUM ('REQUESTED','APPROVED','PICKUP_SCHEDULED','PICKED_UP','RECEIVED','COMPLETED','REJECTED');
CREATE TYPE payout_status AS ENUM ('PENDING','APPROVED','REJECTED','PROCESSED');

CREATE TABLE vendors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone varchar(20) UNIQUE, email citext UNIQUE, auth_provider varchar(20) NOT NULL, status vendor_status NOT NULL DEFAULT 'PENDING_REVIEW', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vendor_profiles (vendor_id uuid PRIMARY KEY REFERENCES vendors(id) ON DELETE CASCADE, full_name varchar(120) NOT NULL, avatar_url text, phone_verified_at timestamptz, email_verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE stores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vendor_id uuid NOT NULL UNIQUE REFERENCES vendors(id), name varchar(160) NOT NULL, slug varchar(180) NOT NULL UNIQUE, description text, vacation_mode boolean NOT NULL DEFAULT false, commission_rate numeric(5,2) NOT NULL DEFAULT 12.00, rating numeric(3,2) DEFAULT 0, follower_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE kyc_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vendor_id uuid NOT NULL REFERENCES vendors(id), status vendor_status NOT NULL DEFAULT 'PENDING_REVIEW', identity_type varchar(30), identity_last4 varchar(4), document_urls jsonb NOT NULL DEFAULT '[]', submitted_at timestamptz, reviewed_at timestamptz, note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE vendor_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vendor_id uuid NOT NULL REFERENCES vendors(id) ON DELETE CASCADE, device varchar(160) NOT NULL, location varchar(160), token_hash text NOT NULL, last_active_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vendor_id uuid NOT NULL REFERENCES vendors(id), token text NOT NULL, platform varchar(20) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(vendor_id, token));
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vendor_id uuid NOT NULL REFERENCES vendors(id), store_id uuid NOT NULL REFERENCES stores(id), name varchar(240) NOT NULL, description text, category varchar(100) NOT NULL, subcategory varchar(100), sku varchar(100) NOT NULL, default_price numeric(12,2) NOT NULL CHECK(default_price >= 0), status product_status NOT NULL DEFAULT 'DRAFT', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(vendor_id, sku));
CREATE INDEX products_vendor_status_idx ON products(vendor_id, status, updated_at DESC);
CREATE TABLE product_images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, url text NOT NULL, alt_text text, sort_order smallint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_prices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, price numeric(12,2) NOT NULL CHECK(price >= 0), starts_at timestamptz, ends_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE city_prices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, city varchar(100) NOT NULL, price numeric(12,2) NOT NULL CHECK(price >= 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(product_id, city));
CREATE TABLE inventory (product_id uuid PRIMARY KEY REFERENCES products(id) ON DELETE CASCADE, vendor_id uuid NOT NULL REFERENCES vendors(id), available_stock integer NOT NULL DEFAULT 0 CHECK(available_stock >= 0), low_stock_threshold integer NOT NULL DEFAULT 10 CHECK(low_stock_threshold >= 0), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX inventory_vendor_stock_idx ON inventory(vendor_id, available_stock);
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id varchar(30) NOT NULL UNIQUE, vendor_id uuid NOT NULL REFERENCES vendors(id), store_id uuid NOT NULL REFERENCES stores(id), customer_name varchar(120) NOT NULL, customer_phone varchar(25), delivery_address jsonb NOT NULL, payment_status varchar(20) NOT NULL, status order_status NOT NULL DEFAULT 'NEW', total_amount numeric(12,2) NOT NULL, placed_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX orders_vendor_status_idx ON orders(vendor_id, status, placed_at DESC);
CREATE TABLE order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id uuid REFERENCES products(id), product_name varchar(240) NOT NULL, quantity integer NOT NULL CHECK(quantity > 0), unit_price numeric(12,2) NOT NULL, subtotal numeric(12,2) NOT NULL);
CREATE TABLE shipments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL UNIQUE REFERENCES orders(id), vendor_id uuid NOT NULL REFERENCES vendors(id), shipment_code varchar(60) NOT NULL UNIQUE, courier varchar(80), pickup_code varchar(40), status varchar(30) NOT NULL DEFAULT 'PREPARING', handover_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE returns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id varchar(30) NOT NULL UNIQUE, order_id uuid NOT NULL REFERENCES orders(id), order_item_id uuid REFERENCES order_items(id), vendor_id uuid NOT NULL REFERENCES vendors(id), customer_name varchar(120) NOT NULL, reason text NOT NULL, status return_status NOT NULL DEFAULT 'REQUESTED', reverse_pickup_status varchar(40), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id), store_id uuid NOT NULL REFERENCES stores(id), vendor_id uuid NOT NULL REFERENCES vendors(id), customer_name varchar(120) NOT NULL, rating smallint NOT NULL CHECK(rating BETWEEN 1 AND 5), body text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE review_responses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), review_id uuid NOT NULL UNIQUE REFERENCES reviews(id) ON DELETE CASCADE, vendor_id uuid NOT NULL REFERENCES vendors(id), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE earnings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL UNIQUE REFERENCES orders(id), vendor_id uuid NOT NULL REFERENCES vendors(id), gross_amount numeric(12,2) NOT NULL, commission_amount numeric(12,2) NOT NULL, net_amount numeric(12,2) NOT NULL, available_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id varchar(30) NOT NULL UNIQUE, vendor_id uuid NOT NULL REFERENCES vendors(id), gross_amount numeric(12,2) NOT NULL, commission_amount numeric(12,2) NOT NULL, net_amount numeric(12,2) NOT NULL, status varchar(20) NOT NULL CHECK(status IN ('PENDING','SETTLED')), settled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE withdrawals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id varchar(30) NOT NULL UNIQUE, vendor_id uuid NOT NULL REFERENCES vendors(id), amount numeric(12,2) NOT NULL CHECK(amount > 0), payment_method varchar(20) NOT NULL, account_masked varchar(60) NOT NULL, status payout_status NOT NULL DEFAULT 'PENDING', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vendor_id uuid NOT NULL REFERENCES vendors(id), type varchar(40) NOT NULL, title varchar(200) NOT NULL, body text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notifications_vendor_unread_idx ON notifications(vendor_id, read_at, created_at DESC);
CREATE TABLE support_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), public_id varchar(30) NOT NULL UNIQUE, vendor_id uuid NOT NULL REFERENCES vendors(id), category varchar(60) NOT NULL, subject varchar(180) NOT NULL, status varchar(30) NOT NULL DEFAULT 'OPEN', attachments jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE, sender_type varchar(20) NOT NULL CHECK(sender_type IN ('VENDOR','SUPPORT')), body text NOT NULL, attachments jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
